<?php
namespace Core;use ZipArchive;require_once __DIR__.'/Guard.php';ml_guard_shield(__FILE__);class XlsxReader{const MAIN_NS='http://schemas.openxmlformats.org/spreadsheetml/2006/main';const REL_NS='http://schemas.openxmlformats.org/package/2006/relationships';const REL_ATTR_NS='http://schemas.openxmlformats.org/officeDocument/2006/relationships';public static function read(string $a):array{if(!is_file($a)){throw new \Exception('文件不存在');}$b=strtolower(pathinfo($a,PATHINFO_EXTENSION));if($b==='csv'){return self::readCsv($a);}if($b!=='xlsx'){if(self::isZip($a)){return self::readXlsx($a);}throw new \Exception('暂不支持旧版 .xls 二进制格式，请先在 Excel / WPS 中「另存为 .xlsx」后再导入');}return self::readXlsx($a);}private static function readCsv(string $a):array{$b=[];$c=fopen($a,'r');if($c===false){throw new \Exception('无法打开文件');}$d=fread($c,3);if($d!=="\xEF\xBB\xBF"){rewind($c);}while(($e=fgetcsv($c,0,','))!==false){if($e===[null]){continue;}$b[]=$e;}fclose($c);return $b;}private static function isZip(string $a):bool{$b=fopen($a,'rb');if($b===false){return false;}$c=fread($b,4);fclose($b);return $c!==false&&substr($c,0,2)==="PK";}private static function readXlsx(string $a):array{if(!class_exists('ZipArchive')){throw new \Exception('服务器未启用 php-zip 扩展，无法解析 xlsx');}$b=new ZipArchive();if($b->open($a)!==true){throw new \Exception('不是有效的 xlsx（无法作为 zip 打开）');}try{$c=self::readSharedStrings($b);$d=self::resolveFirstSheet($b);if($d===''){throw new \Exception('未找到工作表（xl/worksheets/）');}$e=self::getFromZip($b,$d);if($e===false){throw new \Exception('工作表内容读取失败：'.$d);}$f=self::parseSheet($e,$c);}finally{$b->close();}return $f;}private static function readSharedStrings(ZipArchive $a):array{$b='';$c=self::getFromZip($a,'xl/_rels/workbook.xml.rels');if($c!==false&&$c!==''){$d=@simplexml_load_string($c,'SimpleXMLElement',LIBXML_NONET|LIBXML_NOCDATA);if($d!==false){$d->registerXPathNamespace('r',self::REL_NS);$e=$d->xpath('//r:Relationship');if(is_array($e)){foreach($e as $f){if(strpos((string)$f['Type'],'/sharedStrings')!==false){$b=self::resolveTarget((string)$f['Target'],'xl');break;}}}}}$g=[];if($b!==''){$g[]=$b;}$g[]='xl/sharedStrings.xml';foreach($g as $h){$i=self::getFromZip($a,$h);if($i===false||$i===''){continue;}return self::parseSharedStrings($i);}return[];}private static function resolveFirstSheet(ZipArchive $a):string{$b=self::getFromZip($a,'xl/workbook.xml');$c=self::getFromZip($a,'xl/_rels/workbook.xml.rels');if($b!==false&&$c!==false){$d=@simplexml_load_string($b,'SimpleXMLElement',LIBXML_NONET|LIBXML_NOCDATA);$e=@simplexml_load_string($c,'SimpleXMLElement',LIBXML_NONET|LIBXML_NOCDATA);if($d!==false&&$e!==false){$f=[];$e->registerXPathNamespace('r',self::REL_NS);$g=$e->xpath('//r:Relationship');if(is_array($g)){foreach($g as $h){$f[(string)$h['Id']]=(string)$h['Target'];}}$d->registerXPathNamespace('m',self::MAIN_NS);$i=$d->xpath('//m:sheets/m:sheet');if(is_array($i)){foreach($i as $j){$k=$j->attributes(self::REL_ATTR_NS);$l=isset($k['id'])?(string)$k['id']:'';if($l!==''&&!empty($f[$l])){$m=self::resolveTarget($f[$l],'xl');if($m!==''){return $m;}}}}}}for($n=0,$o=$a->numFiles;$n<$o;$n++){$p=(string)$a->getNameIndex($n);if(preg_match('#^xl/worksheets/[^/]+\.xml$#i',$p)){return ltrim($p,'/');}}return'';}private static function resolveTarget(string $a,string $b):string{$a=str_replace('\\','/',trim((string)$a));if($a===''){return'';}if($a[0]==='/'){return ltrim($a,'/');}$c=($b!==''?rtrim($b,'/').'/':'').$a;$d=[];foreach(explode('/',$c)as $e){if($e===''||$e==='.'){continue;}if($e==='..'){array_pop($d);continue;}$d[]=$e;}return implode('/',$d);}private static function getFromZip(ZipArchive $a,string $b){$b=ltrim(str_replace('\\','/',(string)$b),'/');if($b===''){return false;}$c=$a->locateName($b);if($c===false){$c=$a->locateName($b,ZipArchive::FL_NOCASE);}if($c===false){return false;}return $a->getFromIndex($c);}private static function parseSharedStrings(string $a):array{$b=[];$c=@simplexml_load_string($a,'SimpleXMLElement',LIBXML_NONET|LIBXML_NOCDATA);if($c===false){return $b;}$d=$c->children(self::MAIN_NS);if(!isset($d->si)){return $b;}foreach($d->si as $e){$b[]=self::richText($e);}return $b;}private static function richText($a):string{$b='';foreach($a->children(self::MAIN_NS)as $c){$d=$c->getName();if($d==='t'){$b.=(string)$c;}elseif($d==='r'){foreach($c->children(self::MAIN_NS)as $e){if($e->getName()==='t'){$b.=(string)$e;}}}}return $b;}private static function parseSheet(string $a,array $b):array{$c=@simplexml_load_string($a,'SimpleXMLElement',LIBXML_NONET|LIBXML_NOCDATA);if($c===false){throw new \Exception('工作表 XML 解析失败');}$d=$c->children(self::MAIN_NS);if(!isset($d->sheetData)){return[];}$e=[];$f=0;foreach($d->sheetData->children(self::MAIN_NS)as $g){$h=$g->attributes();$i=isset($h['r'])?((int)$h['r']-1):$f;if($i<0){$i=0;}$f=$i+1;$j=[];$k=0;$l=$g->children(self::MAIN_NS);foreach($l as $m){$n=$m->attributes();$o=isset($n['t'])?(string)$n['t']:'n';$p=isset($n['r'])?(string)$n['r']:'';$q=$p!==''?self::colIndex($p):$k;if($q<0){$q=0;}$k=$q+1;$r=$m->children(self::MAIN_NS);$s=isset($r->v)?(string)$r->v:'';switch($o){case's':$t=(int)$s;$u=isset($b[$t])?$b[$t]:'';break;case'inlineStr':$u=isset($r->is)?self::richText($r->is):'';break;case'b':$u=($s==='1')?'1':'0';break;case'e':$u='';break;case'str':case'n':default:$u=$s;break;}$j[$q]=$u;}if(!empty($j)){$e[$i]=$j;}}ksort($e);return array_values($e);}private static function colIndex(string $a):int{if(!preg_match('/^([A-Za-z]+)/',$a,$b)){return-1;}$c=strtoupper($b[1]);$d=strlen($c);$e=0;for($f=0;$f<$d;$f++){$e=$e*26+(ord($c[$f])-64);}return $e-1;}}